import json, pathlib
home = pathlib.Path.home()
d = json.loads((home/".claude/scripts/backup-manifest.json").read_text())
listed = {p["path"] for p in d["paths"]}
dev_listed = {p[len("DEV/"):] for p in listed if p.startswith("DEV/")}

actual = set()
for x in (home/"DEV").iterdir():
    if x.is_dir() and x.name not in {".claude", ".playwright-mcp", "_ARCHIVE", "docs"}:
        actual.add(x.name)
        if x.name == "Football":
            for y in x.iterdir():
                if y.is_dir() and y.name != ".claude":
                    actual.add(f"Football/{y.name}")
actual.discard("Football")

missing = sorted(actual - dev_listed)
gone    = sorted(dev_listed - actual)

print(f"manifest DEV entries: {len(dev_listed)}")
print(f"folders on disk now:  {len(actual)}")
print(f"\nIN MANIFEST BUT NO LONGER ON DISK ({len(gone)}):")
for g in gone: print("   ", g)
print(f"\nON DISK BUT MISSING FROM MANIFEST ({len(missing)}) -> these FAIL the default-deny health check:")
for m in missing: print("   ", m)

print("\n--- which manifest entries push to github? ---")
gh = [p["path"] for p in d["paths"] if "github" in p.get("destinations", [])]
print(f"    {len(gh)} of {len(d['paths'])} paths have 'github' as a destination")

