import zipfile, re, pathlib, difflib
d = pathlib.Path.home()/"DEV/SoftwareTech_Mgmt_Framework/deliverables"
MAC = d/"Software_and_Technology_Management_Framework_DRAFT.edited_ER.docx"
WIN = d/"Software_and_Technology_Management_Framework_DRAFT.edited_ER_WINDOWS-COPY.docx"

def paras(p):
    with zipfile.ZipFile(p) as z:
        xml = z.read("word/document.xml").decode("utf8", "ignore")
    out = []
    for para in re.findall(r"<w:p[ >].*?</w:p>", xml, re.S):
        txt = "".join(re.findall(r"<w:t[^>]*>(.*?)</w:t>", para, re.S))
        txt = re.sub(r"<[^>]+>", "", txt).strip()
        if txt: out.append(txt)
    return out

def parts(p):
    with zipfile.ZipFile(p) as z:
        return z.namelist()

m, w = paras(MAC), paras(WIN)
pm, pw = parts(MAC), parts(WIN)
imgs = lambda ns: [n for n in ns if n.startswith("word/media/")]

print(f"MAC  {MAC.stat().st_size//1024:>4} KB   {len(m):>4} paragraphs   {len(imgs(pm))} embedded images")
print(f"WIN  {WIN.stat().st_size//1024:>4} KB   {len(w):>4} paragraphs   {len(imgs(pw))} embedded images")

print(f"\nsize gap explained by images: {sum(1 for _ in imgs(pw)) - sum(1 for _ in imgs(pm))} more image(s) on Windows")
print(f"tracked changes present — mac: {'yes' if any('word/settings' in x for x in pm) and b'' else ''}", end="")
with zipfile.ZipFile(MAC) as z: mx = z.read("word/document.xml")
with zipfile.ZipFile(WIN) as z: wx = z.read("word/document.xml")
print(f"\nrevision marks (w:ins/w:del) — mac: {mx.count(b'<w:ins ')+mx.count(b'<w:del ')}, win: {wx.count(b'<w:ins ')+wx.count(b'<w:del ')}")
print(f"comments part — mac: {'word/comments.xml' in pm}, win: {'word/comments.xml' in pw}")

if m == w:
    print("\n>>> TEXT IS IDENTICAL. The only difference is embedded media/formatting.")
else:
    sm = difflib.SequenceMatcher(None, m, w)
    print(f"\ntext similarity: {sm.ratio()*100:.1f}%")
    print("\n--- paragraphs ONLY in the Windows copy ---")
    n = 0
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag in ("insert", "replace"):
            for t in w[j1:j2]:
                if n < 12: print("  +", t[:130]); n += 1
    if n == 0: print("  (none)")
    print("\n--- paragraphs ONLY in the Mac copy ---")
    n = 0
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag in ("delete", "replace"):
            for t in m[i1:i2]:
                if n < 12: print("  -", t[:130]); n += 1
    if n == 0: print("  (none)")

